mapper.select:
SELECT r.*,e.authenticity_status FROM kb_source r LEFT JOIN kb_source_profile p ON p.source_id=r.id
LEFT JOIN kb_exam_source e ON e.source_id=r.id AND r.source_kind='EXAM' LEFT JOIN kb_exam_source_detail ed ON ed.source_id=e.source_id

    AND r.title LIKE CONCAT('%',#{title},'%')
    AND p.subject=#{subject}
    AND COALESCE(p.resource_type,'UNKNOWN')=#{resourceType}
    AND COALESCE(p.catalog_status,'DRAFT')=#{catalogStatus}
    AND r.source_kind=#{sourceKind}
    AND r.extraction_status=#{extractionStatus}
    AND e.authenticity_status=#{authenticityStatus}
    AND e.exam_type=#{examPurpose}
    AND ed.organizer_level=#{organizerLevel}
    AND ed.paper_nature=#{paperNature}
    AND e.exam_year=#{examYear}AND ed.academic_year_start=#{academicYearStart}

     AND p.published_yearp.prepared_yeare.exam_yeared.academic_year_start >= #{yearFrom}
     AND p.published_yearp.prepared_yeare.exam_yeared.academic_year_start <= #{yearTo}


      AND EXISTS(SELECT 1 FROM kb_source_outline_scope sc JOIN kb_outline o ON o.id=sc.outline_id WHERE sc.source_id=r.id
       AND sc.outline_id=#{outlineId}
       AND o.textbook_version=#{textbookVersion}
       AND o.grade=#{grade}
       AND o.term=#{term}
       AND (sc.scope_kind='WHOLE_BOOK' OR (sc.scope_kind='CHAPTERS' AND EXISTS(SELECT 1 FROM kb_source_outline_scope_node sn WHERE sn.scope_id=sc.id AND (sn.node_id IN #{n}
        OR sn.node_id IN #{n}))))
      )

    AND EXISTS(SELECT 1 FROM kb_source_region rg WHERE rg.source_id=r.id AND rg.region_role=#{regionRole} AND rg.region_code IN #{code})
    AND EXISTS(SELECT 1 FROM kb_question_source l JOIN kb_question_kp qk ON qk.question_id=l.question_id WHERE l.source_id=r.id AND qk.kp_id=#{kpId})AND EXISTS(SELECT 1 FROM kb_source_kp dk WHERE dk.source_id=r.id AND dk.kp_id=#{kpId})
 ORDER BY r.id DESC
